<# Strategy benchmark data harness. No model dispatch, network, or kernel writes. ASCII-only; PS 5.1+. #>
[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][ValidateSet('validate-corpus','record-run','summarize','list-corpus')][string]$Action,
    [string]$CorpusPath='', [string]$RunJson='', [string]$RunFile='', [string]$RunsFile='', [switch]$Json, [switch]$AllowDesignOnly, [switch]$IncludeDesignOnly
)
$ErrorActionPreference='Stop'
if([string]::IsNullOrWhiteSpace($CorpusPath)){$CorpusPath=Join-Path $PSScriptRoot '..\..\source\registry\strategy-benchmark-corpus.json'}
$script:Strategies=@('single','cascade','critique')
function Restore-JsonMarker($Value){if($null-eq$Value){return $null};if($Value-is[string]){if($Value.StartsWith('__SB_STRING__')){return $Value.Substring(13)};if($Value.Contains('__SB_STRING__')){throw 'INVALID_JSON_MARKER'};return $Value};if($Value-is[array]){$out=New-Object object[] $Value.Count;for($i=0;$i-lt$Value.Count;$i++){$out[$i]=Restore-JsonMarker $Value[$i]};return ,$out};if($Value-is[System.Collections.IDictionary]){foreach($key in @($Value.Keys)){$Value[$key]=Restore-JsonMarker $Value[$key]};return $Value};foreach($property in @($Value.PSObject.Properties)){if($property.MemberType -eq [System.Management.Automation.PSMemberTypes]::NoteProperty){$restored=Restore-JsonMarker $property.Value;$Value|Add-Member -NotePropertyName $property.Name -NotePropertyValue $restored -Force}};return $Value}
function Convert-JsonPreservingTimestamps([string]$Text){$safe=[regex]::Replace($Text,'("(?:started_at|finished_at)"\s*:\s*")','$1__SB_STRING__');$data=$safe|ConvertFrom-Json;return Restore-JsonMarker $data}
function Read-JsonFile([string]$Path){if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){throw "BENCHMARK_FILE_NOT_FOUND: $Path"};$text=[IO.File]::ReadAllText((Resolve-Path -LiteralPath $Path).Path,[Text.Encoding]::UTF8);return Convert-JsonPreservingTimestamps $text}
function Get-Prop($o,[string]$n){$p=$o.PSObject.Properties[$n];if($null -eq $p){return $null};return $p.Value}
function Test-Corpus($d){$e=New-Object 'System.Collections.Generic.List[string]';if([string]$d.schema -cne 'strategy-benchmark-corpus/v1'){$e.Add('INVALID_CORPUS_SCHEMA')};if(@($d.tasks).Count-ne 12){$e.Add('INVALID_TASK_COUNT')};if($d.pilot_ready -isnot [bool]){$e.Add('INVALID_PILOT_READY')};$seen=@{};foreach($t in @($d.tasks)){foreach($n in @('task_id','category','objective','acceptance_criteria','verification_profile','verification_command','fixture','fixture_status','expected_outcome','risk','estimated_tier','allowed_strategies','source_gw','notes')){if($null-eq(Get-Prop $t $n)-and $n-ne'source_gw'){$e.Add("MISSING_FIELD:$n");break}};$id=[string]$t.task_id;if($id -cnotmatch '^sb-(0[1-9]|1[0-2])\z'){$e.Add("INVALID_TASK_ID:$id")};if($seen.ContainsKey($id)){$e.Add("DUPLICATE_TASK_ID:$id")}else{$seen[$id]=$true};if(@($t.allowed_strategies).Count-ne 3-or @($t.allowed_strategies|Where-Object{$script:Strategies -cnotcontains [string]$_}).Count-gt 0){$e.Add("INVALID_STRATEGIES:$id")}};$pilot=@($d.pilot_task_ids);if($pilot.Count-ne 6-or@($pilot|Sort-Object -Unique).Count-ne 6-or@($pilot|Where-Object{$seen.ContainsKey([string]$_)}).Count-ne 6){$e.Add('INVALID_PILOT_TASK_IDS')};foreach($cat in @('small-edit','multi-file-bug','research')){if(@($pilot|Where-Object{$pilotId=$_;@($d.tasks|Where-Object{$_.task_id-ceq$pilotId-and$_.category-ceq$cat}).Count-gt 0}).Count-ne 2){$e.Add("INVALID_PILOT_CATEGORY:$cat")}};$ceiling=((IsNum $d.pilot_cost_ceiling) -and [double]$d.pilot_cost_ceiling -gt 0);if($d.pilot_ready-and(-not$ceiling-or@($d.tasks|Where-Object{$_.fixture_status-ceq'design-only'}).Count-gt 0)){$e.Add('PILOT_READY_PREREQUISITES_MISSING')};if(-not$ceiling-and$d.pilot_ready){$e.Add('INVALID_PILOT_COST_CEILING')};return [pscustomobject]@{ok=($e.Count-eq 0);errors=@($e.ToArray());pilot_ready=([bool]$d.pilot_ready-and$ceiling);pilot_cost_ceiling=$d.pilot_cost_ceiling;pilot_task_ids=$pilot}}
function Get-Corpus{$c=Read-JsonFile $CorpusPath;$v=Test-Corpus $c;if(-not$v.ok){throw ('INVALID_CORPUS: '+($v.errors-join ','))};return $c}
function IsNum($v){return ($v-is[byte]-or $v-is[int16]-or $v-is[int]-or $v-is[long]-or $v-is[double]-or $v-is[decimal]-or $v-is[single])}
function Validate-Run($r,$c,$ids){$e=New-Object 'System.Collections.Generic.List[string]';$required=@('run_id','task_id','strategy','started_at','finished_at','wall_ms','tokens','cost_source','done','verification','human_interventions','dispatches','model_attempts','retries');foreach($n in $required){if($null-eq(Get-Prop $r $n)){$e.Add("MISSING_FIELD:$n")}};if($e.Count){return @($e.ToArray())};if([string]$r.run_id -cnotmatch '^[A-Za-z0-9._-]{1,128}\z'){$e.Add('INVALID_RUN_ID')};if($ids -ccontains [string]$r.run_id){$e.Add('DUPLICATE_RUN_ID')};$task=@($c.tasks|Where-Object{$_.task_id -ceq [string]$r.task_id});if($task.Count-ne 1){$e.Add('UNKNOWN_TASK_ID')}elseif($task[0].allowed_strategies -cnotcontains [string]$r.strategy){$e.Add('STRATEGY_NOT_ALLOWED_FOR_TASK')};if($script:Strategies -cnotcontains [string]$r.strategy){$e.Add('INVALID_STRATEGY')};$start=[DateTimeOffset]::MinValue;$finish=[DateTimeOffset]::MinValue;if(-not[DateTimeOffset]::TryParse([string]$r.started_at,[ref]$start)){$e.Add('INVALID_TIMESTAMP:started_at')};if(-not[DateTimeOffset]::TryParse([string]$r.finished_at,[ref]$finish)){$e.Add('INVALID_TIMESTAMP:finished_at')};if($start-ne[DateTimeOffset]::MinValue-and$finish-ne[DateTimeOffset]::MinValue-and$finish-lt$start){$e.Add('FINISHED_BEFORE_STARTED')};if(-not(IsNum $r.wall_ms)-or[double]$r.wall_ms-lt 0){$e.Add('INVALID_WALL_MS')};foreach($n in @('human_interventions','dispatches','model_attempts','retries')){if(-not(IsNum $r.$n)-or[double]$r.$n-lt 0-or[double]$r.$n-ne[Math]::Truncate([double]$r.$n)){$e.Add("INVALID_COUNT:$n")}};if($r.done-isnot[bool]){$e.Add('INVALID_DONE')};if([string]$r.cost_source -cnotin @('reported','unknown')){$e.Add('INVALID_COST_SOURCE')};if($r.cost_source-ceq'unknown'-and [string]$r.cost-cne'UNKNOWN'){$e.Add('UNKNOWN_COST_MUST_BE_UNKNOWN')};if($r.cost_source-ceq'reported'-and(-not(IsNum $r.cost)-or[double]$r.cost-lt 0)){$e.Add('INVALID_REPORTED_COST')};if($null-eq$r.verification.status-or[string]::IsNullOrWhiteSpace([string]$r.verification.status)){$e.Add('INVALID_VERIFICATION_STATUS')};foreach($f in @('input_tokens','output_tokens','cache_read_tokens','cache_write_tokens')){if($null-eq$r.tokens.$f-or[string]$r.tokens.$f-ceq'UNKNOWN'){continue};if(-not(IsNum $r.tokens.$f)-or[double]$r.tokens.$f-lt 0){$e.Add("INVALID_TOKEN:$f")}};foreach($n in @('rep','order_index','seed','model','tier','fixture_hash','cache_state','strategy_params')){if($null-ne(Get-Prop $r $n)){if($n-in@('rep','order_index','seed')-and(-not(IsNum $r.$n)-or[double]$r.$n-lt 0-or[double]$r.$n-ne[Math]::Truncate([double]$r.$n))){$e.Add("INVALID_OPTIONAL:$n")};if($n-in@('model','tier','fixture_hash','cache_state')-and$r.$n-isnot[string]){$e.Add("INVALID_OPTIONAL:$n")};if($n-eq'strategy_params'-and($null-eq$r.strategy_params.escalations-or$null-eq$r.strategy_params.rounds-or-not(IsNum $r.strategy_params.escalations)-or-not(IsNum $r.strategy_params.rounds)-or[double]$r.strategy_params.escalations-lt 0-or[double]$r.strategy_params.rounds-lt 0-or[double]$r.strategy_params.escalations-ne[Math]::Truncate([double]$r.strategy_params.escalations)-or[double]$r.strategy_params.rounds-ne[Math]::Truncate([double]$r.strategy_params.rounds))){$e.Add('INVALID_OPTIONAL:strategy_params')}}};if($r.done-and[string]::IsNullOrWhiteSpace([string]$r.kernel_ref)-and[string]::IsNullOrWhiteSpace([string]$r.evidence_ref)){$r|Add-Member -NotePropertyName self_reported -NotePropertyValue $true -Force};return @($e.ToArray())}
function RunList([string]$p,$c){$a=@();if(Test-Path -LiteralPath $p){$x=Read-JsonFile $p;if($null-ne$x){$a=@($x)}};$ids=@();$required=@('run_id','task_id','strategy','started_at','finished_at','wall_ms','tokens','cost_source','done','verification','human_interventions','dispatches','model_attempts','retries');foreach($r in $a){foreach($field in $required){if($null-eq(Get-Prop $r $field)){throw "INVALID_RUNS_FILE: MISSING_FIELD:$field"}};$er=Validate-Run $r $c $ids;if($er.Count){throw ('INVALID_RUNS_FILE: '+($er-join ','))};$ids+=,[string]$r.run_id};return ,$a}
 $script:ValidateRunBase=${function:Validate-Run}
function Validate-Run($r,$c,$ids){$errors=@(& $script:ValidateRunBase $r $c $ids);foreach($field in @('input_tokens','output_tokens','cache_read_tokens','cache_write_tokens')){$value=Get-Prop $r.tokens $field;if((IsNum $value) -and [double]$value -ne [math]::Truncate([double]$value)){$errors+=,"INVALID_TOKEN:$field"}};foreach($field in @('design_only','self_reported')){$value=Get-Prop $r $field;if($null-ne$value-and$value-isnot[bool]){$errors+=,"INVALID_BOOLEAN:$field"}};foreach($field in @('seed','order_index','rep')){$value=Get-Prop $r $field;if($null-ne$value){$min=0;if($field-eq'rep'){$min=1};if($value-isnot[int]-and$value-isnot[long]-or[long]$value-lt$min){$errors+=,"INVALID_OPTIONAL:$field"}}};if($null-ne(Get-Prop $r 'critic_session')-and[string]::IsNullOrWhiteSpace([string]$r.critic_session)){$errors+=,'INVALID_CRITIC_SESSION'};if($null-ne(Get-Prop $r 'critic_model')-and[string]::IsNullOrWhiteSpace([string]$r.critic_model)){$errors+=,'INVALID_CRITIC_MODEL'};if($r.strategy-ceq'critique'-and($null-eq$r.critic_model-or$null-eq$r.critic_session-or$null-eq$r.implementer_session-or[string]::IsNullOrWhiteSpace([string]$r.critic_session)-or[string]::IsNullOrWhiteSpace([string]$r.implementer_session))){$errors+=,'CRITIC_EVIDENCE_REQUIRED'};if(@($errors).Count-eq 0-and$r.strategy-ceq'critique'-and[string]$r.critic_session -ieq [string]$r.implementer_session){$errors+=,'CRITIC_SESSION_NOT_INDEPENDENT'};return @($errors)}
function TokenTotal($g,[string]$field){$known=0L;$sum=0L;foreach($r in $g){$v=Get-Prop $r.tokens $field;if(IsNum $v){$known++;$sum += [long]$v}};return [pscustomobject]@{total=$(if($g.Count-gt 0-and$known-eq$g.Count){$sum}else{'UNKNOWN'});token_known_runs=$known}}
function Get-Median([double[]]$v){if(!$v.Count){return $null};$s=@($v|Sort-Object);$m=[int][math]::Floor($s.Count/2);if($s.Count%2){return $s[$m]};return ($s[$m-1]+$s[$m])/2}
function Invoke-BenchmarkSummary {
    if(-not $RunsFile){throw 'INVALID_RUNS_FILE'}
    $c=Get-Corpus;$allRuns=RunList $RunsFile $c
    $designRuns=@($allRuns|Where-Object{$_.design_only -eq $true})
    $excluded=@();if(-not $IncludeDesignOnly){$excluded=$designRuns}
    $runs=@($allRuns|Where-Object{$IncludeDesignOnly -or $_.design_only -ne $true})
    $summaries=New-Object 'System.Collections.Generic.List[object]'
    foreach($strategy in $script:Strategies){
      $group=@($runs|Where-Object{$_.strategy -ceq $strategy})
      $verified=@($group|Where-Object{$_.done -and $_.verification.status -ceq 'verified_pass' -and (-not [string]::IsNullOrWhiteSpace([string]$_.kernel_ref) -or -not [string]::IsNullOrWhiteSpace([string]$_.evidence_ref))})
      $reported=@($group|Where-Object{$_.cost_source -ceq 'reported'});$allCost=($group.Count -gt 0 -and $reported.Count -eq $group.Count)
      $cost='UNKNOWN';if($allCost){$cost=0.0;foreach($item in $reported){$cost += [double]$item.cost}}
      $costPerDone='UNKNOWN';if($verified.Count -gt 0 -and $allCost){$costPerDone=$cost/[double]$verified.Count}
      $tokens=[ordered]@{};foreach($field in @('input_tokens','output_tokens','cache_read_tokens','cache_write_tokens')){$token=TokenTotal $group $field;$tokens[$field]=[ordered]@{total=$token.total;token_known_runs=$token.token_known_runs}}
      $byTask=New-Object 'System.Collections.Generic.List[object]'
      foreach($task in $c.tasks){$taskRuns=@($group|Where-Object{$_.task_id -ceq $task.task_id});if($taskRuns.Count){$taskDone=@($taskRuns|Where-Object{$_.done -and $_.verification.status -ceq 'verified_pass' -and (-not [string]::IsNullOrWhiteSpace([string]$_.kernel_ref) -or -not [string]::IsNullOrWhiteSpace([string]$_.evidence_ref))});$taskSelf=@($taskRuns|Where-Object{$_.self_reported});$taskNoRef=@($taskRuns|Where-Object{[string]::IsNullOrWhiteSpace([string]$_.kernel_ref)-and[string]::IsNullOrWhiteSpace([string]$_.evidence_ref)});$taskIncluded=@($taskRuns|Where-Object{$_.design_only -eq $true}).Count;$byTask.Add([ordered]@{task_id=$task.task_id;runs=$taskRuns.Count;verified_done=$taskDone.Count;unverified_no_ref=$taskNoRef.Count;self_reported=$taskSelf.Count;included_design_only=$(if($IncludeDesignOnly){$taskIncluded}else{0});include_design_only=[bool]$IncludeDesignOnly})}}
      $dispatches=0L;$attempts=0L;$retries=0L;$humans=0L;foreach($item in $group){$dispatches += [long]$item.dispatches;$attempts += [long]$item.model_attempts;$retries += [long]$item.retries;$humans += [long]$item.human_interventions}
      $excludedCount=@($excluded|Where-Object{$_.strategy -ceq $strategy}).Count;$includedCount=0;if($IncludeDesignOnly){$includedCount=@($designRuns|Where-Object{$_.strategy -ceq $strategy}).Count};$noRef=@($group|Where-Object{[string]::IsNullOrWhiteSpace([string]$_.kernel_ref)-and[string]::IsNullOrWhiteSpace([string]$_.evidence_ref)}).Count;$wall=@($group|ForEach-Object{[double]$_.wall_ms})
      $summaries.Add([ordered]@{strategy=$strategy;runs=$group.Count;excluded_design_only=$excludedCount;included_design_only=$includedCount;include_design_only=[bool]$IncludeDesignOnly;done=$verified.Count;unverified_no_ref=$noRef;success_rate=$(if($group.Count){$verified.Count/[double]$group.Count}else{$null});cost_total=$cost;cost_per_verified_done=$costPerDone;known_runs=$reported.Count;observed_vs_unknown=$(if(!$group.Count){'no-runs'}elseif($allCost){'observed'}else{'unknown'});tokens=$tokens;dispatches_total=$dispatches;model_attempts=$attempts;retries=$retries;human_interventions_total=$humans;wall_ms_p50=(Get-Median $wall);by_task=@($byTask.ToArray())})
    }
    $includedTotal=0;if($IncludeDesignOnly){$includedTotal=$designRuns.Count}
    return [ordered]@{schema='strategy-benchmark-summary/v1';total_runs=$runs.Count;excluded_design_only=$excluded.Count;included_design_only=$includedTotal;include_design_only=[bool]$IncludeDesignOnly;strategies=@($summaries.ToArray())}
}
if($Action -eq 'summarize'){$summary=Invoke-BenchmarkSummary;if($Json){ConvertTo-Json -InputObject $summary -Depth 12 -Compress}else{ConvertTo-Json -InputObject $summary -Depth 12};exit 0}
try{switch($Action){
'validate-corpus'{$c=Read-JsonFile $CorpusPath;$o=Test-Corpus $c;if($Json){$o|ConvertTo-Json -Depth 8 -Compress}else{$o|ConvertTo-Json -Depth 8};if(-not$o.ok){exit 1}}
'list-corpus'{$c=Get-Corpus;$o=[pscustomobject]@{pilot_ready=$c.pilot_ready;pilot_cost_ceiling=$c.pilot_cost_ceiling;pilot_task_ids=$c.pilot_task_ids;tasks=$c.tasks};if($Json){$o|ConvertTo-Json -Depth 10 -Compress}else{$o|ConvertTo-Json -Depth 10}}
'record-run'{if(!$RunsFile){throw 'INVALID_RUNS_FILE'};$c=Get-Corpus;$ceiling=((IsNum $c.pilot_cost_ceiling) -and [double]$c.pilot_cost_ceiling -gt 0);if(-not$AllowDesignOnly-and(-not$c.pilot_ready-or-not$ceiling)){throw 'PILOT_NOT_READY: corpus design-only or no approved positive numeric cost ceiling'};if($RunJson-and$RunFile){throw 'INVALID_RUN_INPUT'};$r=if($RunFile){Read-JsonFile $RunFile}else{Convert-JsonPreservingTimestamps $RunJson};if(Test-Path -LiteralPath $RunsFile){$counted=Read-JsonFile $RunsFile;if(@($counted).Count-ge 5000){throw 'RUNS_LIMIT_REACHED'}};$a=RunList $RunsFile $c;$e=Validate-Run $r $c @($a|ForEach-Object{$_.run_id});if($e.Count){throw ('INVALID_RUN: '+($e-join ','))};if($AllowDesignOnly){$r|Add-Member -NotePropertyName design_only -NotePropertyValue $true -Force};$updated=@($a)+@($r);$full=[IO.Path]::GetFullPath($RunsFile);$dir=[IO.Path]::GetDirectoryName($full);if(!(Test-Path -LiteralPath $dir)){[void][IO.Directory]::CreateDirectory($dir)};$tmp=Join-Path $dir ('.'+[IO.Path]::GetFileName($full)+'.'+[guid]::NewGuid().ToString('N')+'.tmp');$bak=$full+'.'+[guid]::NewGuid().ToString('N')+'.bak';try{[IO.File]::WriteAllText($tmp,(ConvertTo-Json -InputObject $updated -Depth 14),[Text.UTF8Encoding]::new($false));if(Test-Path -LiteralPath $full){[IO.File]::Replace($tmp,$full,$bak);Remove-Item -LiteralPath $bak -Force}else{[IO.File]::Move($tmp,$full)}}finally{if(Test-Path -LiteralPath $tmp){Remove-Item -LiteralPath $tmp -Force};if(Test-Path -LiteralPath $bak){Remove-Item -LiteralPath $bak -Force}};[pscustomobject]@{ok=$true;run_id=$r.run_id;count=$updated.Count;self_reported=([bool]$r.self_reported);design_only=([bool]$r.design_only)}|ConvertTo-Json -Compress}
}}
catch{[Console]::Error.WriteLine([string]$_.Exception.Message);exit 1}
